import numpy as np

def solve(x=None, mu=None, sigma=None, p=None):
    if p is not None:
        mean = p
        variance = p * (1.0 - p)
        p_safe = np.clip(p, 1e-12, 1 - 1e-12)
        entropy = -p_safe * np.log2(p_safe) - (1.0 - p_safe) * np.log2(1.0 - p_safe)
        return {
            "mean":     round(float(mean),     4),
            "variance": round(float(variance), 4),
            "entropy":  round(float(entropy),  4),
        }
    pdf = (1.0 / (sigma * np.sqrt(2.0 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    return {"pdf": round(float(pdf), 6)}

