import numpy as np

def init_weights(n_features, strategy="random_normal", seed=42):
    rng = np.random.default_rng(seed)
    if strategy == "zeros":
        weights = np.zeros(n_features)
    elif strategy == "random_normal":
        weights = rng.normal(0, 0.01, n_features)
    elif strategy == "xavier":
        weights = rng.normal(0, np.sqrt(1.0 / n_features), n_features)
    bias = 0.0
    return {
        "weights": [round(float(w), 6) for w in weights],
        "bias": float(bias),
    }

