import numpy as np

def soft_threshold(z, lam):
    return np.sign(z) * np.maximum(np.abs(z) - lam, 0.0)

def lasso_cd(X, y, alpha=1.0, n_iter=500):
    X = np.array(X, dtype=float)
    y = np.array(y, dtype=float)
    n, d = X.shape
    w = np.zeros(d)
    b = 0.0
    for _ in range(n_iter):
        b = float(np.mean(y - X @ w))
        for j in range(d):
            r_j = y - b - X @ w + X[:, j] * w[j]
            z_j = (X[:, j] @ r_j) / n
            col_norm_sq = np.dot(X[:, j], X[:, j]) / n
            w[j] = soft_threshold(z_j, alpha / 2.0) / col_norm_sq
    return {
        "weights": [round(float(wi), 6) for wi in w],
        "bias":    round(float(b), 6),
    }

import numpy as np

def sigmoid(z):
    z = np.array(z, dtype=float)
    result = np.where(z >= 0, 1.0 / (1.0 + np.exp(-np.clip(z, -500, 500))), np.exp(np.clip(z, -500, 500)) / (1.0 + np.exp(np.clip(z, -500, 500))))
    return round(float(result), 6) if result.ndim == 0 else result.round(6).tolist()

def sigmoid_derivative(z):
    z = np.array(z, dtype=float)
    s = np.where(z >= 0, 1.0 / (1.0 + np.exp(-np.clip(z, -500, 500))), np.exp(np.clip(z, -500, 500)) / (1.0 + np.exp(np.clip(z, -500, 500))))
    deriv = s * (1.0 - s)
    return round(float(deriv), 6) if deriv.ndim == 0 else deriv.round(6).tolist()

