from collections import Counter

class DecisionNode:
    def __init__(self, feature=None, threshold=None, left=None, right=None, leaf_class=None):
        self.feature    = feature
        self.threshold  = threshold
        self.left       = left
        self.right      = right
        self.leaf_class = leaf_class


def gini(labels):
    if len(labels) == 0:
        return 0.0
    counts = np.array(list(Counter(labels).values()))
    probs  = counts / len(labels)
    return float(1 - np.sum(probs ** 2))


def best_split(X, y):
    best_gain, best_f, best_t = -1, None, None
    parent_gini = gini(y)
    n = len(y)

    for f in range(X.shape[1]):
