import numpy as np
from collections import Counter

class DecisionNode:
    def __init__(self, feature=None, threshold=None, left=None, right=None, leaf_class=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.leaf_class = leaf_class

def gini(labels):
    if len(labels) == 0:
        return 0.0
    counts = np.array(list(Counter(labels).values()))
    probs = counts / len(labels)
    return float(1 - np.sum(probs ** 2))

def best_split(X, y):
    best_gain, best_f, best_t = -1, None, None
    parent_gini = gini(y)
    n = len(y)
    for f in range(X.shape[1]):
        thresholds = np.unique(X[:, f])
        for t in thresholds:
            left_mask = X[:, f] <= t
            right_mask = ~left_mask
            if left_mask.sum() == 0 or right_mask.sum() == 0:
                continue
            gain = parent_gini - (
                (left_mask.sum() / n) * gini(y[left_mask]) +
                (right_mask.sum() / n) * gini(y[right_mask])
            )
            if gain > best_gain:
                best_gain, best_f, best_t = gain, f, t
    return best_f, best_t

def build_tree(X, y, depth, max_depth):
    if len(np.unique(y)) == 1 or depth >= max_depth:
        leaf_class = int(Counter(y).most_common(1)[0][0])
        return DecisionNode(leaf_class=leaf_class)
    f, t = best_split(X, y)
    if f is None:
        leaf_class = int(Counter(y).most_common(1)[0][0])
        return DecisionNode(leaf_class=leaf_class)
    left_mask = X[:, f] <= t
    right_mask = ~left_mask
    left = build_tree(X[left_mask], y[left_mask], depth + 1, max_depth)
    right = build_tree(X[right_mask], y[right_mask], depth + 1, max_depth)
    return DecisionNode(feature=f, threshold=t, left=left, right=right)

def predict_one(node, x):
    if node.leaf_class is not None:
        return node.leaf_class
    if x[node.feature] <= node.threshold:
        return predict_one(node.left, x)
    else:
        return predict_one(node.right, x)

def decision_tree_classify(X_train, y_train, X_test, y_test, max_depth=3):
    X_tr = np.array(X_train, dtype=float)
    y_tr = np.array(y_train, dtype=int)
    X_te = np.array(X_test, dtype=float)
    y_te = np.array(y_test, dtype=int)
    tree = build_tree(X_tr, y_tr, depth=0, max_depth=max_depth)
    preds = np.array([predict_one(tree, x) for x in X_te])
    accuracy = float(np.mean(preds == y_te))
    return {"test_accuracy": round(accuracy, 4)}

import numpy as np

def _gini(labels):
    if len(labels) == 0:
        return 0.0
    labels = np.asarray(labels)
    classes, counts = np.unique(labels, return_counts=True)
    p = counts / counts.sum()
    return float(1.0 - np.sum(p ** 2))

def _best_split(X, y, feature_indices):
    n = X.shape[0]
    best_score = float("inf")
    best = ()
    for feat in feature_indices:
        values = np.unique(X[:, feat])
        if values.size < 2:
            continue
        thresholds = (values[:-1] + values[1:]) / 2.0
        for thresh in thresholds:
            left_mask = X[:, feat] <= thresh
            right_mask = ~left_mask
            if left_mask.sum() == 0 or right_mask.sum() == 0:
                continue
            g_left = _gini(y[left_mask])
            g_right = _gini(y[right_mask])
            weighted = (left_mask.sum() * g_left + right_mask.sum() * g_right) / n
            if weighted < best_score - 1e-12:
                best_score = weighted
                best = (int(feat), float(thresh))
    return best if best else None

def _majority_label(y):
    classes, counts = np.unique(y, return_counts=True)
    top = counts.max()
    candidates = classes[counts == top]
    return int(candidates.min())

def _build_tree(X, y, depth, max_depth, feature_indices):
    if depth >= max_depth or _gini(y) == 0.0 or len(y) < 2:
        return _majority_label(y)
    split = _best_split(X, y, feature_indices)
    if split is None:
        return _majority_label(y)
    feat, thresh = split
    left_mask = X[:, feat] <= thresh
    right_mask = ~left_mask
    left = _build_tree(X[left_mask], y[left_mask], depth + 1, max_depth, feature_indices)
    right = _build_tree(X[right_mask], y[right_mask], depth + 1, max_depth, feature_indices)
    return {"feature": feat, "threshold": float(thresh), "left": left, "right": right}

def _predict_tree(tree, x):
    if isinstance(tree, dict):
        if x[tree["feature"]] <= tree["threshold"]:
            return _predict_tree(tree["left"], x)
        return _predict_tree(tree["right"], x)
    return tree

def random_forest_predict(train_X, train_y, query_point, n_trees, max_depth, max_features, seed):
    X = np.asarray(train_X, dtype=float)
    y = np.asarray(train_y, dtype=int)
    q = np.asarray(query_point, dtype=float)
    n, d = X.shape
    rng = np.random.default_rng(seed)
    preds = []
    for _ in range(n_trees):
        row_idx = rng.integers(0, n, size=n)
        feat_idx = sorted(rng.choice(d, size=max_features, replace=False).tolist())
        tree = _build_tree(X[row_idx], y[row_idx], 0, max_depth, feat_idx)
        preds.append(_predict_tree(tree, q))
    return _majority_label(np.asarray(preds, dtype=int))

import numpy as np

def kmeans_fit(points, initial_centroids, n_iterations):
    X = np.asarray(points, dtype=float)
    C = np.asarray(initial_centroids, dtype=float).copy()
    k = len(C)
    for _ in range(n_iterations):
        sq_dists = np.sum((X[:, None, :] - C[None, :, :]) ** 2, axis=-1)
        assignments = np.argmin(sq_dists, axis=1)
        for j in range(k):
            mask = assignments == j
            if np.any(mask):
                C[j] = np.mean(X[mask], axis=0)
    sq_dists = np.sum((X[:, None, :] - C[None, :, :]) ** 2, axis=-1)
    assignments = np.argmin(sq_dists, axis=1)
    inertia = float(np.sum(sq_dists[np.arange(len(X)), assignments]))
    return {
        "centroids": np.round(C, 4).tolist(),
        "assignments": [int(a) for a in assignments],
        "inertia": round(inertia, 4),
    }

import numpy as np

def _run_kmeans_inertia(X, initial_centroids, n_iterations):
    C = np.asarray(initial_centroids, dtype=float).copy()
    k = len(C)
    for _ in range(n_iterations):
        sq_dists = np.sum((X[:, None, :] - C[None, :, :]) ** 2, axis=-1)
        assignments = np.argmin(sq_dists, axis=1)
        for j in range(k):
            mask = assignments == j
            if np.any(mask):
                C[j] = np.mean(X[mask], axis=0)
    sq_dists = np.sum((X[:, None, :] - C[None, :, :]) ** 2, axis=-1)
    assignments = np.argmin(sq_dists, axis=1)
    return float(np.sum(sq_dists[np.arange(len(X)), assignments]))

def kmeans_elbow(points, k_values, centroids_by_k, n_iterations):
    X = np.asarray(points, dtype=float)
    raw_inertias = {}
    inertias = {}
    for k in k_values:
        val = _run_kmeans_inertia(X, centroids_by_k[str(k)], n_iterations)
        raw_inertias[k] = val
        inertias[str(k)] = round(val, 4)
    best_drop = -float("inf")
    elbow_k = int(k_values[1])
    for i in range(1, len(k_values)):
        drop = raw_inertias[k_values[i - 1]] - raw_inertias[k_values[i]]
        if drop > best_drop + 1e-12:
            best_drop = drop
            elbow_k = int(k_values[i])
    return {
        "inertias": inertias,
        "elbow_k": elbow_k,
    }

import numpy as np

def eps_neighborhood_stats(points, eps, min_samples):
    X = np.asarray(points, dtype=float)
    dists = np.sqrt(np.sum((X[:, None, :] - X[None, :, :]) ** 2, axis=-1))
    neighbor_counts = np.sum(dists <= eps, axis=1)
    core_points = np.where(neighbor_counts >= min_samples)[0]
    return {
        "neighbor_counts": [int(c) for c in neighbor_counts],
        "core_points": [int(i) for i in core_points],
    }

import numpy as np
from collections import deque

def dbscan_cluster(points, eps, min_samples):
    X = np.asarray(points, dtype=float)
    n = len(X)
    dists = np.sqrt(np.sum((X[:, None, :] - X[None, :, :]) ** 2, axis=-1))
    neighbors = [np.where(dists[i] <= eps)[0].tolist() for i in range(n)]
    is_core = [len(neighbors[i]) >= min_samples for i in range(n)]
    labels = [-1] * n
    expanded = [False] * n
    cluster_id = 0
    for i in range(n):
        if not is_core[i] or labels[i] != -1:
            continue
        labels[i] = cluster_id
        expanded[i] = True
        queue = deque(neighbors[i])
        while queue:
            j = queue.popleft()
            if labels[j] == -1:
                labels[j] = cluster_id
            if is_core[j] and not expanded[j]:
                expanded[j] = True
                for nb in neighbors[j]:
                    queue.append(nb)
        cluster_id += 1
    return {
        "labels": labels,
        "n_clusters": int(cluster_id),
    }

import numpy as np

def perceptron_predict(inputs, weights, bias):
    X = np.asarray(inputs, dtype=float)
    w = np.asarray(weights, dtype=float)
    z = X @ w + float(bias)
    preds = (z >= 0.0).astype(int)
    return {
        "z": [round(float(v), 4) for v in z],
        "predictions": [int(p) for p in preds],
    }

import numpy as np


def dropout_forward(X, keep_prob, seed):
    X = np.array(X, dtype=float)
    rng = np.random.default_rng(seed)
    mask = (rng.random(X.shape) < keep_prob).astype(int)
    out = X * mask / keep_prob
    return {
        "mask": [[int(v) for v in row] for row in mask.tolist()],
        "output": [[round(float(v), 4) for v in row] for row in out.tolist()]
    }

import numpy as np


def pool2d(grid, pool_size, stride, mode):
    g = np.array(grid, dtype=float)
    H, W = g.shape
    out_h = (H - pool_size) // stride + 1
    out_w = (W - pool_size) // stride + 1
    out = np.zeros((out_h, out_w))
    for r in range(out_h):
        for c in range(out_w):
            window = g[r*stride:r*stride+pool_size, c*stride:c*stride+pool_size]
            if mode == "max":
                out[r, c] = np.max(window)
            else:
                out[r, c] = np.mean(window)
    return [[round(float(v), 4) for v in row] for row in out.tolist()]

import numpy as np


def word_embedding_analysis(embedding_matrix, vocab, word_a, word_b):
    mat = np.array(embedding_matrix, dtype=float)
    va = mat[vocab[word_a]]
    vb = mat[vocab[word_b]]

    def cos_sim(u, v):
        nu = np.linalg.norm(u)
        nv = np.linalg.norm(v)
        if nu == 0 or nv == 0:
            return 0.0
        return float(np.dot(u, v) / (nu * nv))

    sim_ab = cos_sim(va, vb)

    # nearest neighbor of word_a
    candidates = []
    for word, idx in vocab.items():
        if word != word_a:
            sim = cos_sim(va, mat[idx])
            candidates.append((word, sim))

    candidates.sort(key=lambda item: (-item[1], item[0]))
    nn_word = candidates[0][0] if candidates else ""

    return {
        "vector_a": [round(float(v), 4) for v in va.tolist()],
        "vector_b": [round(float(v), 4) for v in vb.tolist()],
        "cosine_similarity": round(float(sim_ab), 4),
        "nearest_neighbor_of_a": nn_word
    }

def bpe_tokenize(word_freqs, num_merges, target_word):
    # represent each word as tuple of characters + '</w>'
    splits = {word: list(word) + ["</w>"] for word in word_freqs}

    learned_merges = []
    for _ in range(num_merges):
        pair_counts = {}
        for word, freq in word_freqs.items():
            syms = splits[word]
            for i in range(len(syms) - 1):
                pair = (syms[i], syms[i + 1])
                pair_counts[pair] = pair_counts.get(pair, 0) + freq

        if not pair_counts:
            break

        # best pair: highest count, ties broken by lexicographically smallest
        best_pair = max(pair_counts.keys(), key=lambda p: (pair_counts[p], (-ord(p[0][0]) if False else 0), -1))
        # to properly break ties: sort by (-count, pair)
        best_pair = sorted(pair_counts.keys(), key=lambda p: (-pair_counts[p], p))[0]

        learned_merges.append(list(best_pair))

        # apply merge to all words in corpus
        for word in splits:
            syms = splits[word]
            new_syms = []
            i = 0
            while i < len(syms):
                if i < len(syms) - 1 and (syms[i], syms[i + 1]) == best_pair:
                    new_syms.append(best_pair[0] + best_pair[1])
                    i += 2
                else:
                    new_syms.append(syms[i])
                    i += 1
            splits[word] = new_syms

    # tokenize target_word
    target_syms = list(target_word) + ["</w>"]
    for pair in learned_merges:
        left, right = pair[0], pair[1]
        new_target = []
        i = 0
        while i < len(target_syms):
            if i < len(target_syms) - 1 and target_syms[i] == left and target_syms[i + 1] == right:
                new_target.append(left + right)
                i += 2
            else:
                new_target.append(target_syms[i])
                i += 1
        target_syms = new_target

    return {
        "merges": learned_merges,
        "tokens": target_syms
    }

import numpy as np


def positional_encoding(X):
    X_m = np.array(X, dtype=float)
    seq_len, d_model = X_m.shape

    pe = np.zeros((seq_len, d_model))
    for pos in range(seq_len):
        for i in range(0, d_model, 2):
            denom = 10000.0 ** (i / d_model)
            pe[pos, i] = np.sin(pos / denom)
            if i + 1 < d_model:
                pe[pos, i + 1] = np.cos(pos / denom)

    x_plus_pe = X_m + pe

    return {
        "pe": [[round(float(v), 4) for v in row] for row in pe.tolist()],
        "x_plus_pe": [[round(float(v), 4) for v in row] for row in x_plus_pe.tolist()]
    }

def scale_feature(values):
    n = len(values)
    min_v = min(values)
    max_v = max(values)

    if max_v == min_v:
        minmax = [0.0] * n
    else:
        minmax = [round((x - min_v) / (max_v - min_v), 4) for x in values]

    mean_v = sum(values) / n
    var_v = sum((x - mean_v) ** 2 for x in values) / n
    std_v = var_v ** 0.5

    if std_v == 0.0:
        zscore = [0.0] * n
    else:
        zscore = [round((x - mean_v) / std_v, 4) for x in values]

    return {
        "minmax": minmax,
        "zscore": zscore
    }

def encode_categorical(categories, ordinal_order):
    n = len(categories)
    distinct_sorted = sorted(list(set(categories)))

    one_hot = []
    for cat in categories:
        row = [1 if cat == col else 0 for col in distinct_sorted]
        one_hot.append(row)

    ord_map = {cat: i for i, cat in enumerate(ordinal_order)}
    ordinal = [ord_map[cat] for cat in categories]

    counts = {}
    for cat in categories:
        counts[cat] = counts.get(cat, 0) + 1
    frequency = [round(counts[cat] / n, 4) for cat in categories]

    return {
        "one_hot_columns": distinct_sorted,
        "one_hot": one_hot,
        "ordinal": ordinal,
        "frequency": frequency
    }

def missing_value_report(records, columns, dtypes, threshold):
    missing_per_col = {col: 0 for col in columns}
    for r in records:
        for col in columns:
            if r.get(col) is None:
                missing_per_col[col] += 1

    surviving = []
    dropped_count = 0
    num_cols = len(columns)

    for r in records:
        missing_in_row = sum(1 for col in columns if r.get(col) is None)
        frac = missing_in_row / num_cols if num_cols > 0 else 0.0
        if frac > threshold:
            dropped_count += 1
        else:
            surviving.append(dict(r))

    fill_values = {}
    for col in columns:
        dt = dtypes.get(col, "numeric")
        vals = [r[col] for r in surviving if r.get(col) is not None]
        if not vals:
            fill_values[col] = 0.0 if dt == "numeric" else "UNKNOWN"
        else:
            if dt == "numeric":
                fill_values[col] = round(sum(vals) / len(vals), 4)
            else:
                counts = {}
                for v in vals:
                    counts[v] = counts.get(v, 0) + 1
                sorted_vals = sorted(counts.keys(), key=lambda k: (-counts[k], k))
                fill_values[col] = sorted_vals[0]

    clean_records = []
    for r in surviving:
        clean_r = {}
        for k, v in r.items():
            if k in columns:
                if v is None:
                    clean_r[k] = fill_values[k]
                else:
                    clean_r[k] = round(v, 4) if dtypes.get(k) == "numeric" else v
            else:
                clean_r[k] = v
        clean_records.append(clean_r)

    return {
        "missing_per_column": missing_per_col,
        "rows_dropped": dropped_count,
        "fill_values": fill_values,
        "clean_row_count": len(clean_records),
        "clean_records": clean_records
    }

def engineer_features(records, spec):
    interactions = {}
    for pair in spec.get("interactions", []):
        a, b = pair[0], pair[1]
        col_name = f"{a}_x_{b}"
        interactions[col_name] = [round(float(r[a] * r[b]), 4) for r in records]

    ratios = {}
    for pair in spec.get("ratios", []):
        num, den = pair[0], pair[1]
        col_name = f"{num}_over_{den}"
        vals = []
        for r in records:
            d_val = float(r[den])
            if d_val == 0.0:
                vals.append(None)
            else:
                vals.append(round(float(r[num]) / d_val, 4))
        ratios[col_name] = vals

    bins = {}
    for col, edges in spec.get("bins", {}).items():
        bin_indices = []
        num_buckets = len(edges) - 1
        for r in records:
            v = float(r[col])
            if v <= edges[0]:
                bin_indices.append(0)
            elif v >= edges[-1]:
                bin_indices.append(num_buckets - 1)
            else:
                assigned = False
                for b_idx in range(num_buckets):
                    if b_idx == num_buckets - 1:
                        if edges[b_idx] <= v <= edges[b_idx + 1]:
                            bin_indices.append(b_idx)
                            assigned = True
                            break
                    else:
                        if edges[b_idx] <= v < edges[b_idx + 1]:
                            bin_indices.append(b_idx)
                            assigned = True
                            break
                if not assigned:
                    bin_indices.append(num_buckets - 1)
        bins[col] = bin_indices

    return {
        "interactions": interactions,
        "ratios": ratios,
        "bins": bins
    }

def leakage_demo(values, train_size):
    n = len(values)
    if train_size >= n:
        return {
            "leaky_test_mean": 0.0,
            "correct_test_mean": 0.0,
            "leak_detected": False
        }

    train = values[:train_size]
    test = values[train_size:]

    # leaky: fitted on full
    mean_all = sum(values) / n
    var_all = sum((v - mean_all) ** 2 for v in values) / n
    std_all = var_all ** 0.5
    if std_all == 0:
        scaled_test_leaky = [0.0] * len(test)
    else:
        scaled_test_leaky = [(v - mean_all) / std_all for v in test]

    # correct: fitted on train only
    n_tr = len(train)
    if n_tr == 0:
        mean_tr = 0.0
        std_tr = 0.0
    else:
        mean_tr = sum(train) / n_tr
        var_tr = sum((v - mean_tr) ** 2 for v in train) / n_tr
        std_tr = var_tr ** 0.5

    if std_tr == 0:
        scaled_test_correct = [0.0] * len(test)
    else:
        scaled_test_correct = [(v - mean_tr) / std_tr for v in test]

    leaky_mean = round(sum(scaled_test_leaky) / len(test), 4)
    correct_mean = round(sum(scaled_test_correct) / len(test), 4)
    leak = abs(leaky_mean - correct_mean) > 1e-4

    return {
        "leaky_test_mean": leaky_mean,
        "correct_test_mean": correct_mean,
        "leak_detected": leak
    }

def build_pipeline(records, numeric_columns, categorical_columns, variance_threshold):
    n_rows = len(records)
    missing_filled = {col: 0 for col in numeric_columns + categorical_columns}

    # 1. Impute
    # Numeric: mean, Categorical: mode (ties broken alphabetically)
    num_means = {}
    for col in numeric_columns:
        vals = [r[col] for r in records if r.get(col) is not None]
        num_means[col] = sum(vals) / len(vals) if vals else 0.0

    cat_modes = {}
    for col in categorical_columns:
        vals = [r[col] for r in records if r.get(col) is not None]
        if not vals:
            cat_modes[col] = "UNKNOWN"
        else:
            counts = {}
            for v in vals:
                counts[v] = counts.get(v, 0) + 1
            cat_modes[col] = sorted(counts.keys(), key=lambda k: (-counts[k], k))[0]

    imputed_records = []
    for r in records:
        r_imp = {}
        for col in numeric_columns:
            if r.get(col) is None:
                missing_filled[col] += 1
                r_imp[col] = float(num_means[col])
            else:
                r_imp[col] = float(r[col])
        for col in categorical_columns:
            if r.get(col) is None:
                missing_filled[col] += 1
                r_imp[col] = str(cat_modes[col])
            else:
                r_imp[col] = str(r[col])
        imputed_records.append(r_imp)

    # 2. Encode
    cat_distinct = {}
    for col in categorical_columns:
        cat_distinct[col] = sorted(list(set(r[col] for r in imputed_records)))

    # Order of columns before selection: numeric_columns first, then {col}={category}
    initial_features = list(numeric_columns)
    for col in categorical_columns:
        for cat in cat_distinct[col]:
            initial_features.append(f"{col}={cat}")

    # Build intermediate matrix
    inter_matrix = []
    for r in imputed_records:
        row = []
        for col in numeric_columns:
            row.append(r[col])
        for col in categorical_columns:
            for cat in cat_distinct[col]:
                row.append(1.0 if r[col] == cat else 0.0)
        inter_matrix.append(row)

    # 3. Scale: numeric columns min-max scaled into [0, 1]
    scaled_matrix = [row[:] for row in inter_matrix]
    for j, col in enumerate(numeric_columns):
        col_vals = [inter_matrix[i][j] for i in range(n_rows)]
        min_v = min(col_vals)
        max_v = max(col_vals)
        for i in range(n_rows):
            if max_v == min_v:
                scaled_matrix[i][j] = 0.0
            else:
                scaled_matrix[i][j] = (col_vals[i] - min_v) / (max_v - min_v)

    # 4. Select: drop columns where population variance <= variance_threshold
    surviving_names = []
    surviving_col_idx = []
    dropped_cols = []

    for j, feat_name in enumerate(initial_features):
        vals = [scaled_matrix[i][j] for i in range(n_rows)]
        m_v = sum(vals) / n_rows
        var_v = sum((v - m_v) ** 2 for v in vals) / n_rows
        if var_v <= variance_threshold:
            dropped_cols.append(feat_name)
        else:
            surviving_names.append(feat_name)
            surviving_col_idx.append(j)

    dropped_cols.sort()

    final_matrix = []
    for i in range(n_rows):
        row = [round(float(scaled_matrix[i][j]), 4) for j in surviving_col_idx]
        final_matrix.append(row)

    return {
        "feature_names": surviving_names,
        "model_matrix": final_matrix,
        "pipeline_report": {
            "missing_filled": missing_filled,
            "categories_encoded": cat_distinct,
            "dropped_low_variance": dropped_cols,
            "n_rows": n_rows,
            "n_features_before_selection": len(initial_features),
            "n_features_after_selection": len(surviving_names)
        }
    }

def decompose_additive(values, period):
    n = len(values)
    trend = [None] * n

    if period % 2 == 1:
        k = period // 2
        for i in range(k, n - k):
            window = values[i - k : i + k + 1]
            trend[i] = round(sum(window) / period, 4)
    else:
        k = period // 2
        for i in range(k, n - k):
            s = 0.5 * values[i - k] + sum(values[i - k + 1 : i + k]) + 0.5 * values[i + k]
            trend[i] = round(s / period, 4)

    # Detrended
    detrended = [None if trend[i] is None else values[i] - trend[i] for i in range(n)]

    # Seasonal means per phase p = 0..period-1
    seasonal_sums = [0.0] * period
    seasonal_counts = [0] * period
    for i in range(n):
        if detrended[i] is not None:
            p = i % period
            seasonal_sums[p] += detrended[i]
            seasonal_counts[p] += 1

    seasonal_means = [
        round(seasonal_sums[p] / seasonal_counts[p], 4) if seasonal_counts[p] > 0 else 0.0
        for p in range(period)
    ]

    # Center seasonal means to mean 0
    s_mean = sum(seasonal_means) / period
    seasonal_means = [round(sm - s_mean, 4) for sm in seasonal_means]

    seasonal = [round(seasonal_means[i % period], 4) for i in range(n)]

    residual = [
        None if trend[i] is None else round(values[i] - trend[i] - seasonal[i], 4)
        for i in range(n)
    ]

    return {
        "trend": trend,
        "seasonal_means": seasonal_means,
        "seasonal": seasonal,
        "residual": residual
    }

def lagged_rolling_features(values, window):
    n = len(values)
    lag1 = [None] * n
    rolling_mean = [None] * n
    rolling_std = [None] * n

    for i in range(1, n):
        lag1[i] = round(float(values[i - 1]), 4)

    for i in range(window, n):
        win_vals = values[i - window : i]
        m = sum(win_vals) / window
        rolling_mean[i] = round(float(m), 4)
        if window == 1:
            rolling_std[i] = 0.0
        else:
            var = sum((x - m) ** 2 for x in win_vals) / window
            rolling_std[i] = round(float(var ** 0.5), 4)

    return {
        "lag1": lag1,
        "rolling_mean": rolling_mean,
        "rolling_std": rolling_std
    }

def forecast_errors(actual, predicted):
    n = len(actual)
    mae = sum(abs(a - p) for a, p in zip(actual, predicted)) / n
    rmse = (sum((a - p) ** 2 for a, p in zip(actual, predicted)) / n) ** 0.5

    pe_list = []
    excluded = 0
    for a, p in zip(actual, predicted):
        if a == 0:
            excluded += 1
        else:
            pe_list.append(abs((a - p) / a) * 100.0)

    mape = sum(pe_list) / len(pe_list) if pe_list else 0.0

    return {
        "mae": round(float(mae), 4),
        "rmse": round(float(rmse), 4),
        "mape": round(float(mape), 4),
        "mape_excluded_count": excluded
    }

def seasonal_drift_forecast(values, period, horizon):
    def get_drift(series):
        if len(series) < period + 1:
            return 0.0
        diffs = [series[i + period] - series[i] for i in range(len(series) - period)]
        return sum(diffs) / len(diffs)

    full_drift = get_drift(values)
    future_forecasts = [
        round(values[len(values) - period + h] + full_drift, 4)
        for h in range(horizon)
    ]

    # Backtest on last period points
    train = values[:-period]
    held_out = values[-period:]
    naive_preds = [train[len(train) - period + h] for h in range(period)]
    backtest_mae_naive = round(sum(abs(a - p) for a, p in zip(held_out, naive_preds)) / period, 4)

    train_drift = get_drift(train)
    drift_preds = [train[len(train) - period + h] + train_drift for h in range(period)]
    backtest_mae_drift = round(sum(abs(a - p) for a, p in zip(held_out, drift_preds)) / period, 4)

    improvement = round(backtest_mae_naive - backtest_mae_drift, 4)

    return {
        "future_forecasts": future_forecasts,
        "backtest_mae_naive": backtest_mae_naive,
        "backtest_mae_drift": backtest_mae_drift,
        "improvement": improvement
    }

import numpy as np


def latent_interpolate(z1, z2, alphas, W_dec, b_dec):
    def sigmoid(v):
        v_clip = np.clip(v, -500, 500)
        return 1.0 / (1.0 + np.exp(-v_clip))

    z1_v = np.array(z1, dtype=float)
    z2_v = np.array(z2, dtype=float)
    W_d = np.array(W_dec, dtype=float)
    b_d = np.array(b_dec, dtype=float)

    decodings = []
    for t in alphas:
        z_t = (1.0 - t) * z1_v + t * z2_v
        dec = sigmoid(z_t @ W_d + b_d)
        decodings.append([round(float(v), 4) for v in dec.tolist()])

    return {
        "decodings": decodings
    }

import numpy as np


def generator_forward(noise_batch, Wg1, bg1, Wg2, bg2, Wd1, bd1, Wd2, bd2):
    def sigmoid(v):
        v_clip = np.clip(v, -500, 500)
        return 1.0 / (1.0 + np.exp(-v_clip))

    Z = np.array(noise_batch, dtype=float)
    h_g = sigmoid(Z @ np.array(Wg1, dtype=float) + np.array(bg1, dtype=float))
    generated = sigmoid(h_g @ np.array(Wg2, dtype=float) + np.array(bg2, dtype=float))

    h_d = sigmoid(generated @ np.array(Wd1, dtype=float) + np.array(bd1, dtype=float))
    d_fake = sigmoid(h_d @ np.array(Wd2, dtype=float) + np.array(bd2, dtype=float)).squeeze(-1)

    if d_fake.ndim == 0:
        d_fake = np.array([float(d_fake)])

    d_fake_clip = np.clip(d_fake, 1e-7, 1.0 - 1e-7)
    gen_loss = -np.mean(np.log(d_fake_clip))

    return {
        "generated": [[round(float(v), 4) for v in row] for row in generated.tolist()],
        "d_fake": [round(float(v), 4) for v in d_fake.tolist()],
        "gen_loss": round(float(gen_loss), 4)
    }

import numpy as np


def gan_training_diagnosis(d_losses, g_losses, window):
    k = min(window, len(d_losses))
    recent_d = d_losses[-k:]
    recent_g = g_losses[-k:]

    recent_d_mean = float(np.mean(recent_d))
    recent_g_mean = float(np.mean(recent_g))
    recent_g_std = float(np.std(recent_g, ddof=0))

    if recent_d_mean < 0.1:
        diag = "vanishing_gradient"
    elif recent_g_std < 0.05 and recent_d_mean > 0.5:
        diag = "mode_collapse"
    else:
        diag = "training_normally"

    return {
        "diagnosis": diag,
        "recent_d_mean": round(recent_d_mean, 4),
        "recent_g_mean": round(recent_g_mean, 4),
        "recent_g_std": round(recent_g_std, 4)
    }

import numpy as np


def mdp_metrics(rewards, gamma, reward_table, policy, state):
    disc_return = sum((gamma ** t) * r for t, r in enumerate(rewards))
    p_s = policy[state]
    r_s = reward_table[state]
    exp_r = sum(p_a * r_a for p_a, r_a in zip(p_s, r_s))

    return {
        "discounted_return": round(float(disc_return), 4),
        "expected_reward": round(float(exp_r), 4)
    }

import numpy as np


def epsilon_greedy_counts(q_row, epsilon, n_steps, seed):
    n_actions = len(q_row)
    rng = np.random.default_rng(seed)
    counts = [0] * n_actions

    best_action = int(np.argmax(q_row))

    for _ in range(n_steps):
        coin = rng.random()
        if coin < epsilon:
            a = int(rng.integers(0, n_actions))
        else:
            a = best_action
        counts[a] += 1

    return {
        "action_counts": counts
    }

import numpy as np


def q_table_ops(n_states, n_actions, updates, query_state):
    Q = np.zeros((n_states, n_actions))
    for s, a, val in updates:
        Q[s, a] = val

    best_action = int(np.argmax(Q[query_state]))
    best_value = float(Q[query_state, best_action])

    return {
        "q_table": [[round(float(v), 4) for v in row] for row in Q.tolist()],
        "best_action": best_action,
        "best_value": round(best_value, 4)
    }

import numpy as np


def q_learning_update(n_states, n_actions, transitions, alpha, gamma):
    Q = np.zeros((n_states, n_actions))

    for s, a, r, s_next in transitions:
        if s_next is None:
            target = float(r)
        else:
            target = float(r) + gamma * float(np.max(Q[s_next]))
        Q[s, a] += alpha * (target - Q[s, a])

    return {
        "q_table": [[round(float(v), 4) for v in row] for row in Q.tolist()]
    }

import numpy as np


def dqn_td_targets(rewards, dones, gamma, q_target_next, q_online_all, actions):
    n = len(rewards)
    targets = []
    online_qs = []

    for i in range(n):
        if dones[i]:
            t_i = float(rewards[i])
        else:
            t_i = float(rewards[i]) + gamma * float(max(q_target_next[i]))
        targets.append(t_i)
        online_qs.append(float(q_online_all[i][actions[i]]))

    loss = float(np.mean([(t - q) ** 2 for t, q in zip(targets, online_qs)]))

    return {
        "td_targets": [round(float(t), 4) for t in targets],
        "loss": round(float(loss), 4)
    }

import numpy as np


def rlhf_preference_loss(chosen_scores, rejected_scores):
    def sigmoid(v):
        v_clip = np.clip(v, -500, 500)
        return 1.0 / (1.0 + np.exp(-v_clip))

    c_arr = np.array(chosen_scores, dtype=float)
    r_arr = np.array(rejected_scores, dtype=float)

    prefs = sigmoid(c_arr - r_arr)
    prefs_clip = np.clip(prefs, 1e-9, 1.0 - 1e-9)
    losses = -np.log(prefs_clip)
    mean_l = float(np.mean(losses))

    return {
        "preferences": [round(float(v), 4) for v in prefs.tolist()],
        "losses": [round(float(v), 4) for v in losses.tolist()],
        "mean_loss": round(mean_l, 4)
    }

