def reconcile_sales_report(order_batches, customers, catalog):
    non_empty = [pd.DataFrame(b) for b in order_batches if b]
    if not non_empty:
        return {
            "total_orders": 0,
            "orders_missing_customer": [],
            "orders_missing_category": [],
            "region_category_totals": {},
        }
    df_o = pd.concat(non_empty, ignore_index=True)
    df_c = pd.DataFrame(customers, columns=["customer_id", "region"])
    df_cat = pd.DataFrame(catalog, columns=["product", "category"])
    m1 = pd.merge(df_o, df_c, on="customer_id", how="left")
    m2 = pd.merge(m1, df_cat, on="product", how="left")
    missing_cust = sorted(int(x) for x in m2.loc[m2["region"].isna(), "order_id"].tolist())
    missing_cat = sorted(int(x) for x in m2.loc[m2["category"].isna(), "order_id"].tolist())
    resolved = m2.dropna(subset=["region", "category"])
    grid = {}
    if not resolved.empty:
        grouped = resolved.groupby(["region", "category"])["amount"].sum().round(4)
        for (reg, cat), val in grouped.items():
            grid.setdefault(str(reg), {})[str(cat)] = round(float(val), 4)
    return {
