        "orders_missing_customer": missing_cust,
        "orders_missing_category": missing_cat,
        "region_category_totals": grid,
    }

import pandas as pd

def missing_data_report(records, columns, threshold):
    df = pd.DataFrame(records, columns=columns) if records else pd.DataFrame(columns=columns)
    missing_per_col = {col: int(df[col].isna().sum()) for col in columns}
    if df.empty:
        return {
            "missing_per_column": missing_per_col,
            "rows_dropped": 0,
            "fill_means": {c: 0.0 for c in columns},
            "clean_row_count": 0,
            "clean_records": [],
        }
    frac_missing = df[columns].isna().mean(axis=1)
    surviving = df.loc[frac_missing <= threshold, columns].copy()
    rows_dropped = int(len(df) - len(surviving))
    fill_means = {}
    for col in columns:
        m = surviving[col].mean()
        fill_means[col] = 0.0 if pd.isna(m) else round(float(m), 4)
        surviving[col] = surviving[col].fillna(fill_means[col]).round(4)
    clean_records = [
        {col: round(float(r[col]), 4) for col in columns}
        for _, r in surviving.iterrows()
    ]
    return {
        "missing_per_column": missing_per_col,
        "rows_dropped": rows_dropped,
        "fill_means": fill_means,
        "clean_row_count": int(len(surviving)),
        "clean_records": clean_records,
    }

