import pandas as pd

def detect_outliers(values, method, threshold):
    s = pd.Series(values, dtype="float64")
    if method == "iqr":
        q1 = float(s.quantile(0.25))
        q3 = float(s.quantile(0.75))
        iqr = q3 - q1
        lower = q1 - threshold * iqr
        upper = q3 + threshold * iqr
        mask = (s < lower) | (s > upper)
        bounds = {"lower": round(lower, 4), "upper": round(upper, 4)}
    else:
        mean_val = float(s.mean())
        std_val = float(s.std(ddof=1)) if len(s) >= 2 else 0.0
        if std_val == 0.0 or pd.isna(std_val):
            mask = pd.Series([False] * len(s))
        else:
            mask = ((s - mean_val).abs() / std_val) > threshold
        bounds = {"mean": round(mean_val, 4), "std": round(std_val, 4)}
    indices = [int(i) for i in s.index[mask].tolist()]
    vals = [round(float(x), 4) for x in s[mask].tolist()]
    return {
        "flagged_indices": indices,
        "flagged_values": vals,
        "bounds": bounds,
    }

