def categorize_and_count(records, column, categories):
    df = pd.DataFrame(records)
    lookup = {c.strip().lower(): c for c in categories}
    full_cats = sorted(list(set(categories) | {"Other"}))
    if df.empty:
        return {"counts_per_category": {}, "dtype_categories": full_cats}
    norm = df[column].astype(str).str.strip().str.lower()
    mapped = norm.map(lookup).fillna("Other")
    cat_col = pd.Categorical(mapped, categories=full_cats)
    df["cat"] = cat_col
    counts = df.groupby("cat", observed=True).size()
    return {
        "counts_per_category": {str(k): int(v) for k, v in counts.items() if v > 0},
        "dtype_categories": [str(c) for c in df["cat"].cat.categories.tolist()],
    }

