import pandas as pd

def retail_sales_report(records):
    total_in = len(records)
    if total_in == 0:
        return {
            "monthly_revenue": {},
            "top_store_by_month": {},
            "product_concentration": {},
            "data_quality": {
                "total_rows_in": 0,
                "duplicate_rows_dropped": 0,
                "invalid_rows_dropped": 0,
                "clean_rows": 0,
            },
        }
    df = pd.DataFrame(records)
    dedup = df.drop_duplicates(keep="first").copy()
    dup_dropped = int(total_in - len(dedup))
    clean = dedup.dropna(subset=["qty", "price"]).copy()
    inv_dropped = int(len(dedup) - len(clean))
    if clean.empty:
        return {
            "monthly_revenue": {},
            "top_store_by_month": {},
            "product_concentration": {},
            "data_quality": {
                "total_rows_in": int(total_in),
                "duplicate_rows_dropped": dup_dropped,
                "invalid_rows_dropped": inv_dropped,
                "clean_rows": 0,
            },
        }
    clean["revenue"] = clean["qty"].astype(float) * clean["price"].astype(float)
    clean["month"] = clean["date"].astype(str).str.slice(0, 7)
    m_rev_s = clean.groupby("month")["revenue"].sum().round(2)
    monthly_revenue = {str(k): round(float(v), 2) for k, v in m_rev_s.items()}
    ms_rev = clean.groupby(["month", "store"])["revenue"].sum().reset_index()
    ms_rev = ms_rev.sort_values(by=["month", "revenue", "store"], ascending=[True, False, True])
    top_stores = ms_rev.drop_duplicates(subset=["month"], keep="first")
    top_store_by_month = {str(r["month"]): str(r["store"]) for _, r in top_stores.iterrows()}
    grand_total = float(clean["revenue"].sum())
    prod_rev = clean.groupby("product")["revenue"].sum()
    product_concentration = (
        {str(k): round(float(v / grand_total), 4) for k, v in prod_rev.items()}
        if grand_total > 0 else {}
    )
    return {
        "monthly_revenue": monthly_revenue,
        "top_store_by_month": top_store_by_month,
        "product_concentration": product_concentration,
        "data_quality": {
            "total_rows_in": int(total_in),
            "duplicate_rows_dropped": dup_dropped,
            "invalid_rows_dropped": inv_dropped,
            "clean_rows": int(len(clean)),
        },
    }

import pandas as pd

def analyze_server_logs(records, session_gap_minutes):
    if not records:
        return {
            "user_stats": {},
            "peak_hour": 0,
            "slowest_action": None,
            "action_avg_duration_ms": {},
        }
    df = pd.DataFrame(records)
    df["ts"] = pd.to_datetime(df["timestamp"])
    df = df.sort_values(by=["user", "ts"], kind="mergesort").reset_index(drop=True)
    gaps_min = df.groupby("user")["ts"].diff().dt.total_seconds() / 60.0
    df["new_session"] = gaps_min.isna() | (gaps_min > session_gap_minutes)
    user_stats = {}
    for user, g in df.groupby("user"):
        valid_dur = g["duration_ms"].dropna()
        avg_dur = round(float(valid_dur.mean()), 2) if len(valid_dur) > 0 else 0.0
        user_stats[str(user)] = {
            "event_count": int(len(g)),
            "session_count": int(g["new_session"].sum()),
            "avg_duration_ms": avg_dur,
        }
    df["hour"] = df["ts"].dt.hour
    hour_counts = df.groupby("hour").size()
    max_hc = hour_counts.max()
    peak_hour = int(sorted(int(h) for h, c in hour_counts.items() if c == max_hc)[0])
    dur_df = df.dropna(subset=["duration_ms"])
    if dur_df.empty:
        slowest_action = None
        action_avg = {}
    else:
        act_means = dur_df.groupby("action")["duration_ms"].mean()
        action_avg = {str(k): round(float(v), 2) for k, v in act_means.items()}
        max_act = act_means.max()
        slowest_action = sorted(str(k) for k, v in act_means.items() if v == max_act)[0]
    return {
        "user_stats": user_stats,
        "peak_hour": peak_hour,
        "slowest_action": slowest_action,
        "action_avg_duration_ms": action_avg,
    }

import pandas as pd

SATISFACTION_SCORES = {
    "very satisfied": 5,
    "satisfied": 4,
    "neutral": 3,
    "unsatisfied": 2,
    "very unsatisfied": 1,
}
KNOWN_SEGMENTS = {"enterprise", "smb", "consumer"}

def survey_quality_report(responses):
    if not responses:
        return {
            "segment_avg_satisfaction": {},
            "response_quality": {
                "total_responses": 0,
                "missing_satisfaction": 0,
                "unrecognized_satisfaction": 0,
                "low_quality_flagged": 0,
            },
            "segment_counts": {},
        }
    df = pd.DataFrame(responses)
    def clean_seg(val):
        if val is None or pd.isna(val):
            return "other"
        s = str(val).strip().lower()
        return s if s in KNOWN_SEGMENTS else "other"
    df["canon_seg"] = df["segment"].apply(clean_seg)
    missing_sat = df["satisfaction"].isna()
    sat_norm = df["satisfaction"].dropna().astype(str).str.strip().str.lower()
    df["score"] = sat_norm.map(SATISFACTION_SCORES)
    unrec_sat = (~missing_sat) & df["score"].isna()
    empty_comment = df["comment"].isna() | (df["comment"].astype(str).str.strip() == "")
    low_qual = missing_sat | unrec_sat | empty_comment
    scored = df.dropna(subset=["score"])
    seg_avg = {
        str(k): round(float(v), 2)
        for k, v in scored.groupby("canon_seg")["score"].mean().items()
    }
    seg_counts = {
        str(k): int(v)
        for k, v in df.groupby("canon_seg").size().items()
    }
    return {
        "segment_avg_satisfaction": seg_avg,
        "response_quality": {
            "total_responses": int(len(df)),
            "missing_satisfaction": int(missing_sat.sum()),
            "unrecognized_satisfaction": int(unrec_sat.sum()),
            "low_quality_flagged": int(low_qual.sum()),
        },
        "segment_counts": seg_counts,
    }

