def where_and_select(values, low, high):
    arr = np.array(values, dtype=np.float64)
    clipped = np.where(arr > high, float(high), arr)
    tiers = np.select([arr < low, arr > high], ["low", "high"], default="mid")
    tier_list = [str(t) for t in tiers.tolist()]
    return {
        "clipped_binary": clipped.tolist(),
        "tier_labels": tier_list,
        "tier_counts": {
            "low": int(tier_list.count("low")),
            "mid": int(tier_list.count("mid")),
            "high": int(tier_list.count("high")),
        },
    }

