def make_minibatches(values, n_batches):
    arr = np.array(values)
    if len(arr) % n_batches == 0:
        method = "split"
        chunks = np.split(arr, n_batches)
    else:
        method = "array_split"
        chunks = np.array_split(arr, n_batches)
    return {
        "method": method,
        "batches": [c.tolist() for c in chunks],
        "batch_sizes": [int(len(c)) for c in chunks],
    }

import numpy as np

def moving_stats(values, window):
    arr = np.array(values, dtype=np.float64)
    wins = np.lib.stride_tricks.sliding_window_view(arr, window_shape=window)
    return {
        "moving_means": [round(float(x), 4) for x in wins.mean(axis=-1).tolist()],
        "moving_maxes": [round(float(x), 4) for x in wins.max(axis=-1).tolist()],
    }

def parse_records(raw_lines, fields, delimiter):
    out = []
    n_fields = len(fields)
    for line in raw_lines:
        parts = line.split(delimiter)
        if len(parts) == n_fields:
            out.append({k: p.strip() for k, p in zip(fields, parts)})
    return out

def coerce_types(records, schema):
    failure_counts = {k: 0 for k in schema}
    out_records = []
    for rec in records:
        new_rec = dict(rec)
        for field, target_type in schema.items():
            if field not in new_rec or new_rec[field] is None:
                failure_counts[field] += 1
                continue
            val = new_rec[field]
            try:
                if target_type == "int":
                    if isinstance(val, bool):
                        raise ValueError("bool is not int")
                    new_rec[field] = int(val)
                elif target_type == "float":
                    if isinstance(val, bool):
                        raise ValueError("bool is not float")
                    new_rec[field] = float(val)
                elif target_type == "str":
                    new_rec[field] = str(val)
            except (ValueError, TypeError):
                failure_counts[field] += 1
        out_records.append(new_rec)
    return {
        "records": out_records,
        "failure_counts": failure_counts,
    }

def validate_schema(records, required_fields, range_rules):
    valid_count = 0
    errors = []
    for idx, rec in enumerate(records):
        reasons = []
        for req in required_fields:
            if req not in rec or rec[req] is None or rec[req] == "":
                reasons.append(f"missing_field:{req}")
        for field, bounds in range_rules.items():
            if field in rec and rec[field] is not None:
                val = rec[field]
                if isinstance(val, bool) or not isinstance(val, (int, float)):
                    reasons.append(f"not_numeric:{field}")
                else:
                    lo, hi = bounds
                    if val < lo or val > hi:
                        reasons.append(f"out_of_range:{field}")
        if reasons:
            errors.append({"index": int(idx), "reasons": sorted(reasons)})
        else:
            valid_count += 1
    return {
        "valid_count": int(valid_count),
        "errors": errors,
    }

def quarantine_batch(records, required_fields, range_rules):
    valid = []
    quarantine = []
    for rec in records:
        reasons = []
        for req in required_fields:
            if req not in rec or rec[req] is None or rec[req] == "":
                reasons.append(f"missing_field:{req}")
        for field, bounds in range_rules.items():
            if field in rec and rec[field] is not None:
                val = rec[field]
                if isinstance(val, bool) or not isinstance(val, (int, float)):
                    reasons.append(f"not_numeric:{field}")
                else:
                    lo, hi = bounds
                    if val < lo or val > hi:
                        reasons.append(f"out_of_range:{field}")
        if reasons:
            quarantine.append({"record": dict(rec), "reasons": sorted(reasons)})
        else:
            valid.append(dict(rec))
    return {
        "valid": valid,
        "quarantine": quarantine,
        "counts": {"valid": int(len(valid)), "quarantined": int(len(quarantine))},
    }

def batch_metadata(records, timestamp_field, amount_field):
    if not records:
        return {
            "record_count": 0,
            "min_timestamp": None,
            "max_timestamp": None,
            "checksum": 0.0,
        }
    ts_list = [str(r[timestamp_field]) for r in records]
    total_amt = sum(float(r[amount_field]) for r in records)
    return {
        "record_count": int(len(records)),
        "min_timestamp": min(ts_list),
        "max_timestamp": max(ts_list),
        "checksum": round(float(total_amt), 4),
    }

def ingest_batch(raw_lines, fields, delimiter, schema, required_fields, range_rules, timestamp_field, amount_field):
    valid = []
    quarantine = []
    parsed_count = 0
    n_fields = len(fields)
    for line in raw_lines:
        parts = line.split(delimiter)
        if len(parts) != n_fields:
            quarantine.append({"record": {"raw_line": line}, "reasons": ["parse_error"]})
            continue
        parsed_count += 1
        rec = {k: p.strip() for k, p in zip(fields, parts)}
        for f, t in schema.items():
            if f in rec and rec[f] is not None:
                try:
                    if t == "int":
                        rec[f] = int(rec[f])
                    elif t == "float":
                        rec[f] = float(rec[f])
                    elif t == "str":
                        rec[f] = str(rec[f])
                except (ValueError, TypeError):
                    pass
        reasons = []
        for req in required_fields:
            if req not in rec or rec[req] is None or rec[req] == "":
                reasons.append(f"missing_field:{req}")
        for f, bounds in range_rules.items():
            if f in rec and rec[f] is not None:
                val = rec[f]
                if isinstance(val, bool) or not isinstance(val, (int, float)):
                    reasons.append(f"not_numeric:{f}")
                else:
                    lo, hi = bounds
                    if val < lo or val > hi:
                        reasons.append(f"out_of_range:{f}")
        if reasons:
            quarantine.append({"record": rec, "reasons": sorted(reasons)})
        else:
            valid.append(rec)
    if valid:
        ts_list = [str(r[timestamp_field]) for r in valid]
        meta = {
            "record_count": int(len(valid)),
            "min_timestamp": min(ts_list),
            "max_timestamp": max(ts_list),
            "checksum": round(float(sum(float(r[amount_field]) for r in valid)), 4),
        }
    else:
        meta = {
            "record_count": 0,
            "min_timestamp": None,
            "max_timestamp": None,
            "checksum": 0.0,
        }
    return {
        "valid": valid,
        "quarantine": quarantine,
        "counts": {
            "parsed": int(parsed_count),
            "valid": int(len(valid)),
            "quarantined": int(len(quarantine)),
        },
        "metadata": meta,
    }

def dedup_by_key(records, key_field, timestamp_field):
    best_by_key = {}
    for rec in records:
        k = str(rec[key_field])
        ts = str(rec[timestamp_field])
        if k not in best_by_key or ts > str(best_by_key[k][timestamp_field]):
            best_by_key[k] = dict(rec)
    kept = [best_by_key[k] for k in sorted(best_by_key.keys())]
    return {
        "kept": kept,
        "removed_count": int(len(records) - len(kept)),
    }

def normalize_values(records, field, canonical_map, casing):
    out = []
    for rec in records:
        new_rec = dict(rec)
        if field in new_rec and new_rec[field] is not None:
            val = str(new_rec[field])
            low_key = val.lower()
            mapped = canonical_map.get(low_key, val)
            if casing == "lower":
                mapped = mapped.lower()
            elif casing == "upper":
                mapped = mapped.upper()
            elif casing == "title":
                mapped = mapped.title()
            new_rec[field] = mapped
        out.append(new_rec)
    return out

def apply_missing_policy(records, policy):
    surviving = []
    dropped = 0
    filled_default = 0
    filled_derived = 0
    drop_fields = [f for f, p in policy.items() if p.get("strategy") == "drop"]
    for rec in records:
        if any(f not in rec or rec[f] is None for f in drop_fields):
            dropped += 1
            continue
        new_rec = dict(rec)
        for f, p in policy.items():
            strat = p.get("strategy")
            if strat == "drop":
                continue
            is_missing = (f not in new_rec) or (new_rec[f] is None)
            if is_missing:
                if strat == "fill_default":
                    new_rec[f] = p["value"]
                    filled_default += 1
                elif strat == "fill_derived":
                    src = p["source"]
                    if src in new_rec and new_rec[src] is not None:
                        new_rec[f] = new_rec[src]
                        filled_derived += 1
                    else:
                        new_rec[f] = None
        surviving.append(new_rec)
    return {
        "records": surviving,
        "action_counts": {
            "dropped": int(dropped),
            "filled_default": int(filled_default),
            "filled_derived": int(filled_derived),
        },
    }

import pandas as pd

def flag_outliers(records, field, method, params):
    if method == "fixed":
        lo = float(params["min"])
        hi = float(params["max"])
    else:
        vals = [
            float(r[field])
            for r in records
            if field in r and r[field] is not None and not isinstance(r[field], bool) and isinstance(r[field], (int, float))
        ]
        if not vals:
            return {"flagged_indices": [], "fence": {"low": 0.0, "high": 0.0}}
        s = pd.Series(vals, dtype="float64")
        q1 = float(s.quantile(0.25))
        q3 = float(s.quantile(0.75))
        iqr = q3 - q1
        k = float(params["multiplier"])
        lo = q1 - k * iqr
        hi = q3 + k * iqr
    flagged = []
    for idx, r in enumerate(records):
        if field in r and r[field] is not None and not isinstance(r[field], bool) and isinstance(r[field], (int, float)):
            v = float(r[field])
            if v < lo or v > hi:
                flagged.append(int(idx))
    return {
        "flagged_indices": flagged,
        "fence": {"low": round(float(lo), 4), "high": round(float(hi), 4)},
    }

def find_orphans(children, parent_ids, fk_field):
    valid_parents = set(parent_ids)
    orphan_indices = []
    clean_count = 0
    for idx, child in enumerate(children):
        fk = child.get(fk_field)
        if fk is None or fk not in valid_parents:
            orphan_indices.append(int(idx))
        else:
            clean_count += 1
    return {
        "orphan_indices": orphan_indices,
        "orphan_count": int(len(orphan_indices)),
        "clean_count": int(clean_count),
    }

def harden_feed(records, key_field, timestamp_field, normalize_field, canonical_map, casing, missing_policy, parent_ids, fk_field):
    input_count = len(records)
    best_by_key = {}
    for rec in records:
        k = str(rec[key_field])
        ts = str(rec[timestamp_field])
        if k not in best_by_key or ts > str(best_by_key[k][timestamp_field]):
            best_by_key[k] = dict(rec)
    deduped = [best_by_key[k] for k in sorted(best_by_key.keys())]
    duplicates_removed = input_count - len(deduped)

    normed = []
    for rec in deduped:
        new_rec = dict(rec)
        if normalize_field in new_rec and new_rec[normalize_field] is not None:
            val = str(new_rec[normalize_field])
            mapped = canonical_map.get(val.lower(), val)
            if casing == "lower":
                mapped = mapped.lower()
            elif casing == "upper":
                mapped = mapped.upper()
            elif casing == "title":
                mapped = mapped.title()
            new_rec[normalize_field] = mapped
        normed.append(new_rec)

    drop_fields = [f for f, p in missing_policy.items() if p.get("strategy") == "drop"]
    clean = []
    missing_dropped = 0
    missing_filled = 0
    for rec in normed:
        if any(f not in rec or rec[f] is None for f in drop_fields):
            missing_dropped += 1
            continue
        new_rec = dict(rec)
        for f, p in missing_policy.items():
            strat = p.get("strategy")
            if strat == "drop":
                continue
            if f not in new_rec or new_rec[f] is None:
                if strat == "fill_default":
                    new_rec[f] = p["value"]
                    missing_filled += 1
                elif strat == "fill_derived":
                    src = p["source"]
                    if src in new_rec and new_rec[src] is not None:
                        new_rec[f] = new_rec[src]
                        missing_filled += 1
                    else:
                        new_rec[f] = None
        clean.append(new_rec)

    clean.sort(key=lambda r: str(r[key_field]))
    parent_set = set(parent_ids)
    orphans_found = sum(1 for r in clean if r.get(fk_field) is None or r.get(fk_field) not in parent_set)
    return {
        "clean": clean,
        "audit": {
            "input_count": int(input_count),
            "duplicates_removed": int(duplicates_removed),
            "missing_dropped": int(missing_dropped),
            "missing_filled": int(missing_filled),
            "orphans_found": int(orphans_found),
            "output_count": int(len(clean)),
        },
    }

def enrich_records(records, lookup_field, lookup_table, target_field, default_value):
    out = []
    miss_count = 0
    for rec in records:
        new_rec = dict(rec)
        key = new_rec.get(lookup_field)
        if key is None or key not in lookup_table:
            new_rec[target_field] = default_value
            miss_count += 1
        else:
            new_rec[target_field] = lookup_table[key]
        out.append(new_rec)
    return {
        "records": out,
        "miss_count": int(miss_count),
    }

def route_records(records, rules):
    routes = {r["name"]: [] for r in rules}
    routes["default"] = []
    for idx, rec in enumerate(records):
        matched_dest = "default"
        for rule in rules:
            field = rule["field"]
            if field not in rec or rec[field] is None:
                continue
            val = rec[field]
            target = rule["value"]
            op = rule["op"]
            ok = False
            if op == "eq":
                ok = (val == target)
            elif op == "gt":
                ok = (val > target)
            elif op == "lt":
                ok = (val < target)
            elif op == "gte":
                ok = (val >= target)
            elif op == "lte":
                ok = (val <= target)
            if ok:
                matched_dest = rule["name"]
                break
        routes[matched_dest].append(int(idx))
    return routes

def derive_fields(records, key_fields, bucket_field, bucket_edges, bucket_labels):
    out = []
    n_buckets = len(bucket_labels)
    for rec in records:
        new_rec = dict(rec)
        parts = []
        for kf in key_fields:
            v = new_rec.get(kf)
            parts.append("none" if v is None else str(v))
        new_rec["composite_key"] = "-".join(parts)
        b_val = new_rec.get(bucket_field)
        bucket = None
        if b_val is not None and not isinstance(b_val, bool) and isinstance(b_val, (int, float)):
            for i in range(n_buckets):
                lo = bucket_edges[i]
                hi = bucket_edges[i + 1]
                if i < n_buckets - 1:
                    if lo <= b_val < hi:
                        bucket = bucket_labels[i]
                        break
                else:
                    if lo <= b_val <= hi:
                        bucket = bucket_labels[i]
                        break
        new_rec["bucket"] = bucket
        out.append(new_rec)
    return out

def upsert_batch(store, batch, id_field):
    new_store = {str(k): dict(v) for k, v in store.items()}
    inserted = 0
    updated = 0
    no_op = 0
    for rec in batch:
        key = str(rec[id_field])
        rec_copy = dict(rec)
        if key not in new_store:
            new_store[key] = rec_copy
            inserted += 1
        elif new_store[key] == rec_copy:
            no_op += 1
        else:
            new_store[key] = rec_copy
            updated += 1
    return {
        "store": new_store,
        "inserted": int(inserted),
        "updated": int(updated),
        "no_op": int(no_op),
    }

def run_pipeline(records, stages):
    curr = [dict(r) for r in records]
    stage_counts = []
    for st in stages:
        op = st["op"]
        in_c = len(curr)
        nxt = []
        if op == "filter":
            f = st["field"]
            cmp_op = st["op_cmp"]
            target = st["value"]
            for r in curr:
                if f not in r or r[f] is None:
                    continue
                v = r[f]
                keep = (
                    (v == target) if cmp_op == "eq" else
                    (v > target) if cmp_op == "gt" else
                    (v < target) if cmp_op == "lt" else
                    (v >= target) if cmp_op == "gte" else
                    (v <= target) if cmp_op == "lte" else False
                )
                if keep:
                    nxt.append(dict(r))
        elif op == "set_field":
            f = st["field"]
            val = st["value"]
            for r in curr:
                nr = dict(r)
                nr[f] = val
                nxt.append(nr)
        elif op == "drop_field":
            f = st["field"]
            for r in curr:
                nr = dict(r)
                nr.pop(f, None)
                nxt.append(nr)
        elif op == "rename_field":
            src = st["from"]
            dst = st["to"]
            for r in curr:
                nr = dict(r)
                if src in nr:
                    nr[dst] = nr.pop(src)
                nxt.append(nr)
        curr = nxt
        stage_counts.append({"op": str(op), "in_count": int(in_c), "out_count": int(len(curr))})
    return {
        "records": curr,
        "stage_counts": stage_counts,
    }

def transform_stage(records, lookup_field, lookup_table, target_field, default_value,
                     bucket_field, bucket_edges, bucket_labels, id_field, store):
    new_store = {str(k): dict(v) for k, v in store.items()}
    inserted = 0
    updated = 0
    no_op = 0
    n_buckets = len(bucket_labels)
    for rec in records:
        nr = dict(rec)
        lkey = nr.get(lookup_field)
        if lkey is None or lkey not in lookup_table:
            nr[target_field] = default_value
        else:
            nr[target_field] = lookup_table[lkey]
        b_val = nr.get(bucket_field)
        bucket = None
        if b_val is not None and not isinstance(b_val, bool) and isinstance(b_val, (int, float)):
            for i in range(n_buckets):
                lo, hi = bucket_edges[i], bucket_edges[i + 1]
                if (i < n_buckets - 1 and lo <= b_val < hi) or (i == n_buckets - 1 and lo <= b_val <= hi):
                    bucket = bucket_labels[i]
                    break
        nr["bucket"] = bucket
        ukey = str(nr[id_field])
        if ukey not in new_store:
            new_store[ukey] = nr
            inserted += 1
        elif new_store[ukey] == nr:
            no_op += 1
        else:
            new_store[ukey] = nr
            updated += 1
    return {
        "store": new_store,
        "inserted": int(inserted),
        "updated": int(updated),
        "no_op": int(no_op),
    }

from datetime import datetime

def bucket_events(events, granularity):
    buckets = {}
    for ev in events:
        ts = str(ev["timestamp"])
        key = ts[:10] if granularity == "daily" else ts[:13] + ":00:00"
        if key not in buckets:
            buckets[key] = {"count": 0, "sum": 0.0}
        buckets[key]["count"] += 1
        buckets[key]["sum"] = round(buckets[key]["sum"] + float(ev["value"]), 4)
    return buckets

from copy import deepcopy
from datetime import datetime

def apply_late_record(buckets, record, watermark):
    new_buckets = deepcopy(buckets)
    rec_date = str(record["timestamp"])[:10]
    wm_date = str(watermark)[:10]
    is_late = rec_date < wm_date
    if rec_date not in new_buckets:
        new_buckets[rec_date] = {"count": 0, "sum": 0.0}
    new_buckets[rec_date]["count"] += 1
    new_buckets[rec_date]["sum"] = round(float(new_buckets[rec_date]["sum"]) + float(record["value"]), 4)
    return {
        "buckets": new_buckets,
        "bucket_key": rec_date,
        "is_late": bool(is_late),
    }

def rollup_hierarchy(records, hierarchy):
    city_totals = {}
    region_totals = {}
    country_totals = {}
    for rec in records:
        city = str(rec["city"])
        val = float(rec["value"])
        city_totals[city] = round(city_totals.get(city, 0.0) + val, 4)
        if city in hierarchy:
            reg = str(hierarchy[city]["region"])
            cnt = str(hierarchy[city]["country"])
            region_totals[reg] = round(region_totals.get(reg, 0.0) + val, 4)
            country_totals[cnt] = round(country_totals.get(cnt, 0.0) + val, 4)
    return {
        "city_totals": city_totals,
        "region_totals": region_totals,
        "country_totals": country_totals,
    }

def check_metrics_consistency(raw_records, stored_rollup, tolerance):
    recomputed = {}
    for r in raw_records:
        k = str(r["key"])
        recomputed[k] = round(recomputed.get(k, 0.0) + float(r["value"]), 4)
    drifted = {}
    for k in sorted(set(recomputed.keys()) & set(stored_rollup.keys())):
        rec_v = float(recomputed[k])
        sto_v = float(stored_rollup[k])
        rel_diff = abs(rec_v - sto_v) / max(abs(rec_v), abs(sto_v), 1.0)
        if rel_diff > tolerance:
            drifted[k] = {
                "recomputed": round(rec_v, 4),
                "stored": round(sto_v, 4),
                "diff": round(rec_v - sto_v, 4),
            }
    missing_in_stored = sorted(set(recomputed.keys()) - set(stored_rollup.keys()))
    missing_in_raw = sorted(set(stored_rollup.keys()) - set(recomputed.keys()))
    is_consistent = (len(drifted) == 0 and len(missing_in_stored) == 0 and len(missing_in_raw) == 0)
    return {
        "recomputed": recomputed,
        "drifted": drifted,
        "missing_in_stored": missing_in_stored,
        "missing_in_raw": missing_in_raw,
        "is_consistent": bool(is_consistent),
    }

from datetime import datetime, timedelta

def run_rollup_engine(batches, watermark_lag_hours):
    rollups = {}
    processing_log = []
    total_late = 0
    max_ts_dt = None
    watermark_date = None

    for b in batches:
        b_id = str(b["batch_id"])
        recs = b["records"]
        late_count = 0
        for r in recs:
            ts_str = str(r["timestamp"])
            dt = datetime.fromisoformat(ts_str)
            b_date = ts_str[:10]
            if watermark_date is not None and b_date < watermark_date:
                late_count += 1
            if b_date not in rollups:
                rollups[b_date] = {"count": 0, "sum": 0.0}
            rollups[b_date]["count"] += 1
            rollups[b_date]["sum"] = round(rollups[b_date]["sum"] + float(r["value"]), 4)
            if max_ts_dt is None or dt > max_ts_dt:
                max_ts_dt = dt
        if max_ts_dt is not None:
            wm_dt = max_ts_dt - timedelta(hours=float(watermark_lag_hours))
            watermark_date = wm_dt.strftime("%Y-%m-%d")
        total_late += late_count
        processing_log.append({
            "batch_id": b_id,
            "records_processed": int(len(recs)),
            "late_count": int(late_count),
        })
    return {
        "rollups": rollups,
        "processing_log": processing_log,
        "total_late": int(total_late),
    }

def enrich_records(events, reference, miss_policy):
    all_ref_fields = set()
    for ref_val in reference.values():
        all_ref_fields.update(ref_val.keys())
    enriched = []
    unmatched = []
    for ev in events:
        rk = ev["ref_key"]
        if rk in reference:
            merged = dict(ev)
            merged.update(reference[rk])
            enriched.append(merged)
        else:
            unmatched.append(str(ev["id"]))
            if miss_policy == "null":
                merged = dict(ev)
                for rf in all_ref_fields:
                    merged[rf] = None
                enriched.append(merged)
    enriched.sort(key=lambda r: str(r["id"]))
    unmatched.sort()
    return {
        "enriched": enriched,
        "unmatched": unmatched,
    }

def detect_changes(yesterday, today):
    y_keys = set(yesterday.keys())
    t_keys = set(today.keys())
    added = sorted(t_keys - y_keys)
    removed = sorted(y_keys - t_keys)
    changed = {}
    for k in sorted(y_keys & t_keys):
        y_rec = yesterday[k]
        t_rec = today[k]
        all_fields = sorted(set(y_rec.keys()) | set(t_rec.keys()))
        diffs = {}
        for f in all_fields:
            old_v = y_rec.get(f, None)
            new_v = t_rec.get(f, None)
            if old_v != new_v or (f in y_rec) != (f in t_rec):
                if old_v != new_v:
                    diffs[f] = {"old": old_v, "new": new_v}
        if diffs:
            changed[k] = diffs
    return {
        "added": added,
        "removed": removed,
        "changed": changed,
    }

import copy

def apply_scd_lite(history, key, new_attributes, effective_date):
    new_hist = copy.deepcopy(history)
    if key not in new_hist or len(new_hist[key]) == 0:
        new_hist[key] = [{
            "attributes": copy.deepcopy(new_attributes),
            "valid_from": str(effective_date),
            "valid_to": None,
        }]
        return new_hist
    versions = new_hist[key]
    open_ver = versions[-1]
    if open_ver["attributes"] == new_attributes:
        return new_hist
    open_ver["valid_to"] = str(effective_date)
    versions.append({
        "attributes": copy.deepcopy(new_attributes),
        "valid_from": str(effective_date),
        "valid_to": None,
    })
    return new_hist

def reconcile_sources(source_a, source_b, tolerance):
    keys_a = set(source_a.keys())
    keys_b = set(source_b.keys())
    only_a = sorted(keys_a - keys_b)
    only_b = sorted(keys_b - keys_a)
    matched = []
    value_mismatch = {}
    for k in sorted(keys_a & keys_b):
        va = float(source_a[k])
        vb = float(source_b[k])
        rel = abs(va - vb) / max(abs(va), abs(vb), 1.0)
        if rel <= tolerance:
            matched.append(k)
        else:
            value_mismatch[k] = {
                "a": round(va, 4),
                "b": round(vb, 4),
                "diff": round(va - vb, 4),
            }
    return {
        "matched": matched,
        "value_mismatch": value_mismatch,
        "only_a": only_a,
        "only_b": only_b,
        "summary": {
            "matched": int(len(matched)),
            "mismatched": int(len(value_mismatch)),
            "only_a": int(len(only_a)),
            "only_b": int(len(only_b)),
        },
    }

def resolve_conflicts(record_a, record_b, rules, source_priority):
    meta_keys = {"timestamp", "source"}
    data_fields = sorted((set(record_a.keys()) | set(record_b.keys())) - meta_keys)
    resolved = {}
    conflicts = []
    ts_a = str(record_a.get("timestamp", ""))
    ts_b = str(record_b.get("timestamp", ""))
    src_a = record_a.get("source")
    src_b = record_b.get("source")
    rank_a = source_priority.index(src_a) if src_a in source_priority else len(source_priority)
    rank_b = source_priority.index(src_b) if src_b in source_priority else len(source_priority)

    for f in data_fields:
        in_a = f in record_a
        in_b = f in record_b
        if in_a and not in_b:
            resolved[f] = record_a[f]
            conflicts.append(f)
            continue
        if in_b and not in_a:
            resolved[f] = record_b[f]
            conflicts.append(f)
            continue
        va = record_a[f]
        vb = record_b[f]
        if va != vb:
            conflicts.append(f)
        rule = rules.get(f, "latest_timestamp")
        if rule == "latest_timestamp":
            resolved[f] = vb if ts_b > ts_a else va
        elif rule == "max":
            resolved[f] = vb if vb > va else va
        elif rule == "source_priority":
            resolved[f] = vb if rank_b < rank_a else va
        else:
            resolved[f] = vb if ts_b > ts_a else va
    return {
        "resolved": resolved,
        "conflicts": sorted(conflicts),
    }

from datetime import datetime
from collections import defaultdict

def process_clickstream(events, session_gap_minutes):
    if not events:
        return {"sessions": [], "daily_rollup": {}}
    by_user = defaultdict(list)
    for ev in events:
        by_user[str(ev["user"])].append(ev)
    sessions = []
    for user, u_events in by_user.items():
        u_sorted = sorted(u_events, key=lambda e: str(e["timestamp"]))
        sess_id = 1
        curr_events = [u_sorted[0]]
        for ev in u_sorted[1:]:
            prev_dt = datetime.fromisoformat(str(curr_events[-1]["timestamp"]))
            curr_dt = datetime.fromisoformat(str(ev["timestamp"]))
            gap_min = (curr_dt - prev_dt).total_seconds() / 60.0
            if gap_min > session_gap_minutes:
                start_ts = str(curr_events[0]["timestamp"])
                end_ts = str(curr_events[-1]["timestamp"])
                dur = (datetime.fromisoformat(end_ts) - datetime.fromisoformat(start_ts)).total_seconds()
                sessions.append({
                    "user": user,
                    "session_id": int(sess_id),
                    "event_count": int(len(curr_events)),
                    "start": start_ts,
                    "end": end_ts,
                    "duration_seconds": round(float(dur), 4),
                    "pages": [str(x["page"]) for x in curr_events],
                })
                sess_id += 1
                curr_events = [ev]
            else:
                curr_events.append(ev)
        start_ts = str(curr_events[0]["timestamp"])
        end_ts = str(curr_events[-1]["timestamp"])
        dur = (datetime.fromisoformat(end_ts) - datetime.fromisoformat(start_ts)).total_seconds()
        sessions.append({
            "user": user,
            "session_id": int(sess_id),
            "event_count": int(len(curr_events)),
            "start": start_ts,
            "end": end_ts,
            "duration_seconds": round(float(dur), 4),
            "pages": [str(x["page"]) for x in curr_events],
        })
    sessions.sort(key=lambda s: (s["start"], s["user"]))
    daily_rollup = {}
    for s in sessions:
        day = s["start"][:10]
        if day not in daily_rollup:
            daily_rollup[day] = {"session_count": 0, "event_count": 0}
        daily_rollup[day]["session_count"] += 1
        daily_rollup[day]["event_count"] += int(s["event_count"])
    return {
        "sessions": sessions,
        "daily_rollup": daily_rollup,
    }

from collections import Counter

def run_quality_suite(tables, rules):
    rule_results = {}
    rules_passed = 0
    for rule in rules:
        rid = str(rule["rule_id"])
        rtype = str(rule["type"])
        tname = str(rule["table"])
        field = str(rule["field"])
        rows = tables.get(tname, [])
        checked = 0
        failed = 0
        failing_raw = []

        if rtype == "completeness":
            checked = len(rows)
            for r in rows:
                v = r.get(field)
                if v is None:
                    failed += 1
                    failing_raw.append("null")
        elif rtype == "uniqueness":
            non_null_vals = [r.get(field) for r in rows if r.get(field) is not None]
            checked = len(non_null_vals)
            counts = Counter(non_null_vals)
            for r in rows:
                v = r.get(field)
                if v is not None and counts[v] > 1:
                    failed += 1
                    failing_raw.append(v)
        elif rtype == "range":
            checked = len(rows)
            lo = float(rule["min"])
            hi = float(rule["max"])
            for r in rows:
                v = r.get(field)
                if v is None:
                    failed += 1
                    failing_raw.append("null")
                elif isinstance(v, bool) or not isinstance(v, (int, float)) or v < lo or v > hi:
                    failed += 1
                    failing_raw.append(v)
        elif rtype == "referential":
            ref_rows = tables.get(str(rule["ref_table"]), [])
            ref_field = str(rule["ref_field"])
            valid_refs = {rr.get(ref_field) for rr in ref_rows if rr.get(ref_field) is not None}
            for r in rows:
                v = r.get(field)
                if v is not None:
                    checked += 1
                    if v not in valid_refs:
                        failed += 1
                        failing_raw.append(v)

        passed = (failed == 0)
        if passed:
            rules_passed += 1
        capped = failing_raw[:5]
        capped_sorted = sorted(capped, key=lambda x: str(x))
        rule_results[rid] = {
            "type": rtype,
            "passed": bool(passed),
            "checked": int(checked),
            "failed": int(failed),
            "failing_samples": capped_sorted,
        }

    total = len(rules)
    score = round(rules_passed / float(total), 4) if total > 0 else 0.0
    return {
        "rule_results": rule_results,
        "summary": {
            "rules_total": int(total),
            "rules_passed": int(rules_passed),
            "score": score,
        },
    }

