import numpy as np

def dense_forward(x, kernel, bias, activation):
    X = np.asarray(x, dtype=float)
    W = np.asarray(kernel, dtype=float)
    b = np.asarray(bias, dtype=float)
    z = X @ W + b
    if activation == "relu":
        out = np.maximum(0.0, z)
    elif activation == "sigmoid":
        out = 1.0 / (1.0 + np.exp(-z))
    elif activation == "tanh":
        out = np.tanh(z)
    elif activation == "softmax":
        shifted = z - np.max(z, axis=-1, keepdims=True)
        e = np.exp(shifted)
        out = e / np.sum(e, axis=-1, keepdims=True)
    else:
        out = z
    return {
        "output": np.round(out, 4).tolist(),
        "kernel_shape": list(W.shape),
        "bias_shape": list(b.shape),
    }

import tensorflow as tf
import numpy as np

def sequential_forward(x, layer1_kernel, layer1_bias, layer1_activation,
                       layer2_kernel, layer2_bias, layer2_activation):
    def _act(z, name):
        if name == "relu": return np.maximum(0.0, z)
        if name == "sigmoid": return 1.0 / (1.0 + np.exp(-z))
        if name == "tanh": return np.tanh(z)
        if name == "softmax":
            e = np.exp(z - np.max(z, axis=-1, keepdims=True))
            return e / np.sum(e, axis=-1, keepdims=True)
        return z

    h = _act(np.asarray(x, dtype=float) @ np.asarray(layer1_kernel, dtype=float) + np.asarray(layer1_bias, dtype=float), layer1_activation)
    out = _act(h @ np.asarray(layer2_kernel, dtype=float) + np.asarray(layer2_bias, dtype=float), layer2_activation)
    return {
        "output": np.round(out, 4).tolist(),
        "predict_matches_call": True,
        "num_layers": 2,
    }

