import numpy as np

def build_and_forward(x_batch, layer_specs):
    curr = np.asarray(x_batch, dtype=float)
    total_params = 0
    for sp in layer_specs:
        K = np.asarray(sp["kernel"], dtype=float)
        b = np.asarray(sp["bias"], dtype=float)
        in_f, units = K.shape
        total_params += in_f * units + len(b)
        curr = curr @ K + b
        act = sp.get("activation")
        if act == "relu":
            curr = np.maximum(0.0, curr)
        elif act == "sigmoid":
            curr = 1.0 / (1.0 + np.exp(-curr))
        elif act == "tanh":
            curr = np.tanh(curr)
    return {
        "output": np.round(curr, 4).tolist(),
        "num_layers": len(layer_specs),
        "total_params": int(total_params),
    }

