def reshape_schema(records, rename_map, drop_cols):
    if not records:
        return []
    cols = list(records[0].keys())
    for old_c, new_c in rename_map.items():
        cols = [new_c if c == old_c else c for c in cols]
    drop_set = set(drop_cols)
    keep_cols = [c for c in cols if c not in drop_set]
    out = []
    for r in records:
        d = dict(r)
        for old_c, new_c in rename_map.items():
            if old_c in d:
                d[new_c] = d.pop(old_c)
        out.append({c: d.get(c) for c in keep_cols})
    out.sort(key=lambda r: tuple((r.get(c) is None, r.get(c)) for c in keep_cols))
    return out

