        prods = {x["product"] for x in rows}
        tot = sum(amounts)
        out.append({
            "region": reg,
            "total_amount": tot,
            "avg_amount": round(tot / len(amounts), 4),
            "distinct_products": len(prods),
            "num_orders": len(rows),
        })
    return out

