def left_and_outer_join(employees, departments):
    dept_by_id = {}
    for d in departments:
        did = d.get("dept_id")
        if did is not None:
            dept_by_id.setdefault(did, []).append(d)

    left_rows = []
    matched_depts = set()
    for e in employees:
        did = e.get("dept_id")
        if did is not None and did in dept_by_id:
            matched_depts.add(did)
            for d in dept_by_id[did]:
                left_rows.append({
                    "dept_id": did,
                    "emp_id": e["emp_id"],
                    "name": e["name"],
                    "dept_name": d["dept_name"],
                    "budget": d["budget"],
                })
        else:
            left_rows.append({
                "dept_id": did,
                "emp_id": e["emp_id"],
                "name": e["name"],
                "dept_name": None,
                "budget": None,
            })

    outer_rows = [dict(r) for r in left_rows]
    for d in departments:
        did = d.get("dept_id")
        if did not in matched_depts:
            outer_rows.append({
                "dept_id": did,
                "emp_id": None,
                "name": None,
                "dept_name": d["dept_name"],
                "budget": d["budget"],
            })

    def sort_key(r):
        return (
            (r["emp_id"] is not None, r["emp_id"]),
            (r["dept_name"] is not None, r["dept_name"]),
            (r["dept_id"] is not None, r["dept_id"]),
        )

    left_rows.sort(key=sort_key)
    outer_rows.sort(key=sort_key)
    return {"left": left_rows, "outer": outer_rows}

