def reconcile_customers(primary, backup, regions):
    reg_map = {r["region_code"]: r["region_name"] for r in regions if r.get("region_code") is not None}
    tagged = []
    for r in primary:
        tagged.append((r["customer_id"], 0, dict(r)))
    for r in backup:
        tagged.append((r["customer_id"], 1, dict(r)))
    tagged.sort(key=lambda x: (x[0], x[1]))

    seen = set()
    reconciled = []
    for cid, prio, row in tagged:
        if cid not in seen:
            seen.add(cid)
            rc = row.get("region_code")
            reconciled.append({
                "customer_id": cid,
                "name": row["name"],
                "region_code": rc,
                "region_name": reg_map.get(rc) if rc is not None else None,
            })

    reconciled.sort(key=lambda r: r["customer_id"])
    total_in = len(primary) + len(backup)
    no_match = sum(1 for r in reconciled if r["region_name"] is None)
    return {
        "customers": reconciled,
        "stats": {
            "total_rows_in": total_in,
            "duplicates_dropped": total_in - len(reconciled),
            "no_region_match": no_match,
        },
    }

def rank_by_department(employees):
    by_dept = {}
    for e in employees:
        by_dept.setdefault(e["department"], []).append(dict(e))
    out = []
    for dept in sorted(by_dept.keys()):
        rows = sorted(by_dept[dept], key=lambda r: -r["salary"])
        for idx, r in enumerate(rows, 1):
            r["dept_rank"] = idx
            out.append(r)
    return out

def leaderboard_rankings(scores):
    by_cat = {}
    for s in scores:
        by_cat.setdefault(s["category"], []).append(dict(s))
    out = []
    for cat in sorted(by_cat.keys()):
        rows = sorted(by_cat[cat], key=lambda r: -r["score"])
        distinct_desc = sorted({r["score"] for r in rows}, reverse=True)
        drk_map = {val: i + 1 for i, val in enumerate(distinct_desc)}
        for idx, r in enumerate(rows, 1):
            r["rn"] = idx
            r["rk"] = next(j + 1 for j, x in enumerate(rows) if x["score"] == r["score"])
            r["drk"] = drk_map[r["score"]]
            out.append(r)
    return out

