    }

def rank_over_time(records):
    by_cat_per = {}
    for r in records:
        by_cat_per.setdefault((r["category"], r["period"]), []).append(dict(r))

    ranked = []
    for (cat, per), rows in by_cat_per.items():
        rows.sort(key=lambda x: (-x["score"], x["entity"]))
        for i, r in enumerate(rows):
            r["rank"] = next(j + 1 for j, x in enumerate(rows) if x["score"] == r["score"])
            ranked.append(r)

    by_cat_ent = {}
    for r in ranked:
        by_cat_ent.setdefault((r["category"], r["entity"]), []).append(r)

    for (cat, ent), rows in by_cat_ent.items():
        rows.sort(key=lambda x: x["period"])
        for i, r in enumerate(rows):
            if i == 0:
                r["movement"] = None
            else:
                r["movement"] = rows[i - 1]["rank"] - r["rank"]

    ranked.sort(key=lambda r: (r["category"], r["period"], r["rank"], r["entity"]))

    pos_movers = [r for r in ranked if r["movement"] is not None and r["movement"] > 0]
    best_mover = None
    if pos_movers:
        pos_movers.sort(key=lambda r: (-r["movement"], r["entity"], r["period"], r["category"]))
        bm = pos_movers[0]
        best_mover = {
            "category": bm["category"],
            "period": bm["period"],
            "entity": bm["entity"],
            "movement": bm["movement"],
        }

    return {
        "rankings": [
            {
                "category": r["category"],
                "period": r["period"],
                "entity": r["entity"],
                "score": r["score"],
                "rank": r["rank"],
                "movement": r["movement"],
            }
            for r in ranked
        ],
        "best_mover": best_mover,
        "stats": {
            "total_rows": len(records),
            "periods_tracked": len({r["period"] for r in records}),
            "entities_tracked": len({r["entity"] for r in records}),
        },
    }

