def log_analytics_report(records, session_gap_minutes):
    if not records:
        return {"user_activity": {}, "peak_hour": 0, "peak_hour_count": 0, "endpoint_counts": []}
    by_user = {}
    hour_counts = {}
    ep_counts = {}
    for r in records:
        by_user.setdefault(r["user"], []).append(r["minute_of_day"])
        h = r["hour"]
        hour_counts[h] = hour_counts.get(h, 0) + 1
        ep = r["endpoint"]
        ep_counts[ep] = ep_counts.get(ep, 0) + 1

    user_activity = {}
    for u in sorted(by_user.keys()):
        mins = sorted(by_user[u])
        sessions = 1 if mins else 0
        for i in range(1, len(mins)):
            if mins[i] - mins[i - 1] > session_gap_minutes:
                sessions += 1
        user_activity[u] = {"event_count": len(mins), "session_count": sessions}

    peak_hour = min(hour_counts.keys(), key=lambda h: (-hour_counts[h], h))
    endpoint_list = [
        {"endpoint": ep, "count": cnt}
        for ep, cnt in sorted(ep_counts.items(), key=lambda x: (-x[1], x[0]))
    ]
    return {
        "user_activity": user_activity,
        "peak_hour": peak_hour,
        "peak_hour_count": hour_counts[peak_hour],
        "endpoint_counts": endpoint_list,
    }

