def sales_pipeline_report(orders, products, reps):
    prod_map = {p["product_id"]: p["price"] for p in products}
    rep_map = {r["rep_id"]: r["region"] for r in reps}

    unmatched_prod = 0
    unmatched_rep = 0
    used_orders = 0
    rollup_totals = {}

    for o in orders:
        pid = o["product_id"]
        if pid not in prod_map:
            unmatched_prod += 1
            continue
        price = prod_map[pid]
        rid = o["rep_id"]
        if rid not in rep_map:
            unmatched_rep += 1
            continue
        used_orders += 1
        reg = rep_map[rid]
        rollup_totals[(reg, rid)] = rollup_totals.get((reg, rid), 0.0) + o["qty"] * price

    rep_rollup = [
        {"region": reg, "rep_id": rid, "total_revenue": round(rev, 2)}
        for (reg, rid), rev in rollup_totals.items()
    ]
    rep_rollup.sort(key=lambda r: (r["region"], -r["total_revenue"], r["rep_id"]))

    top_rep_by_region = {}
    for r in rep_rollup:
        reg = r["region"]
        if reg not in top_rep_by_region:
            top_rep_by_region[reg] = r["rep_id"]

    return {
        "rep_rollup": rep_rollup,
        "top_rep_by_region": top_rep_by_region,
        "data_quality": {
            "total_orders": len(orders),
            "unmatched_product_orders": unmatched_prod,
            "unmatched_rep_orders": unmatched_rep,
            "orders_used_in_revenue": used_orders,
        },
    }

