def data_quality_report(orders, customers):
    cust_ids = {c["customer_id"] for c in customers}
    null_cid = sum(1 for o in orders if o.get("customer_id") is None)
    null_amt = sum(1 for o in orders if o.get("amount") is None)

    seen = set()
    dup_count = 0
    for o in orders:
        key = (o.get("order_id"), o.get("customer_id"), o.get("amount"))
        if key in seen:
            dup_count += 1
        else:
            seen.add(key)

    orphan_ids = sorted([
        o["order_id"]
        for o in orders
        if o.get("customer_id") is not None and o.get("customer_id") not in cust_ids
    ])

    return {
        "total_orders": len(orders),
        "null_audit": {
            "customer_id": null_cid,
            "amount": null_amt,
        },
        "duplicate_row_count": dup_count,
        "referential_orphans": {
            "count": len(orphan_ids),
            "order_ids": orphan_ids,
        },
    }
